"""Fixed four-arm comparison using source/runtime arms independent of transport mode."""
import argparse
from collections import Counter
import json
import os
from pathlib import Path
import signal
import statistics
import subprocess
import time

from runtime_identity import (HERE, ROOT, ORIGINAL_SOURCE, ORIGINAL_SOURCES, canonical_sha,
                              classpath_manifest, original_identity, sha, write_new)

MAIN = 'org.eclipse.rdf4j.sail.lmdb.evaluation.RootQualifiedOptionalFanoutLauncher'
PROPERTY = 'rdf4j.lmdb.resultCoordinateTransport'
ARMS = ['original-off', 'original-dense', 'candidate1-dense', 'candidate1-and-2-dense']
METRICS = ['totalNs', 'prepareNs', 'evaluateNs', 'consumeNs', 'allThreadAllocatedBytes',
           'callerThreadAllocatedBytes', 'ledgerPeakBytes']
PAIRS = [('original-dense', 'original-off'), ('candidate1-dense', 'original-dense'),
         ('candidate1-and-2-dense', 'candidate1-dense'), ('candidate1-dense', 'original-off'),
         ('candidate1-and-2-dense', 'original-off'), ('candidate1-and-2-dense', 'original-dense')]


def verified_file(path, expected):
    path = Path(path).resolve(strict=True)
    if not expected or sha(path) != expected:
        raise ValueError(f'Identity mismatch: {path}')
    return path


def validate_protocol(protocol_path):
    protocol = json.loads(protocol_path.read_text())
    if protocol.get('status') != 'frozen-ready':
        raise ValueError('Protocol remains a draft; runtime identities must be filled and frozen first')
    if protocol['arms'] != ARMS or protocol['warmup'] != 8 or protocol['iterations'] != 5 or protocol['rounds'] != 4:
        raise ValueError('Unexpected change to prespecified arm/count design')
    orders = [[ARMS[i] for i in order] for order in ([0,1,3,2],[1,2,0,3],[2,3,1,0],[3,0,2,1])]
    if protocol['balancedOrders'] != orders:
        raise ValueError('Expected the prespecified four-arm Williams square')
    expected_arms = {'original-off':{'runtime':'original','transportMode':'off'},
                     'original-dense':{'runtime':'original','transportMode':'dense'},
                     'candidate1-dense':{'runtime':'candidate1','transportMode':'dense'},
                     'candidate1-and-2-dense':{'runtime':'candidate1-and-2','transportMode':'dense'}}
    if protocol['armDefinitions'] != expected_arms:
        raise ValueError('Runtime/source arm and transport-mode mapping changed')
    if protocol['java'] != '/workspace/scratch/d0a0e51b9386/toolchain/jdk-25.0.5+8/bin/java':
        raise ValueError('Unexpected JDK path; rebasing requires a separately documented protocol')
    verified_file(Path(__file__), protocol['driverSha256'])
    verified_file(HERE / 'runtime_identity.py', protocol['identityHelperSha256'])
    original_cp, original_manifest = original_identity()
    snapshots = {}
    for name in ('original', 'candidate1', 'candidate1-and-2'):
        descriptor = protocol['runtimes'][name]
        if not isinstance(descriptor, dict):
            raise ValueError(f'Runtime unresolved: {name}')
        cp_file = verified_file(descriptor['classpathFile'], descriptor['classpathFileSha256'])
        mf_file = verified_file(descriptor['classpathManifestFile'], descriptor['classpathManifestSha256'])
        verified_file(descriptor['sourceManifestFile'], descriptor['sourceManifestSha256'])
        provenance_file = verified_file(descriptor['provenanceFile'], descriptor['provenanceSha256'])
        provenance = json.loads(provenance_file.read_text())
        if name != 'original':
            verified_file(descriptor['productionPatchFile'], descriptor['productionPatchSha256'])
            if (provenance['sourceIdentity'] != descriptor['sourceIdentity'] or provenance['name'] != name
                    or provenance['unchangedOtherEntries'] != 126 or provenance['replacedIndex'] != 1
                    or provenance['originalSourceMapSha256'] != sha(ORIGINAL_SOURCES)):
                raise ValueError(f'Candidate source provenance mismatch: {name}')
            source_map = json.loads(Path(descriptor['sourceManifestFile']).read_text())
            if descriptor['sourceIdentity'] != '15fe7d5011+followup-source-map-sha256-' + canonical_sha(source_map):
                raise ValueError(f'Candidate source identity does not match its source map: {name}')
        baseline_file = verified_file(descriptor['originalSourceManifestFile'], descriptor['originalSourceManifestSha256'])
        if baseline_file != ORIGINAL_SOURCES.resolve():
            raise ValueError('Runtime descriptor does not name the exact original measured source map')
        cp = cp_file.read_text().strip()
        observed = classpath_manifest(cp)
        if observed != json.loads(mf_file.read_text()) or len(observed) != 127:
            raise ValueError(f'Runtime artifact identity mismatch: {name}')
        if name == 'original':
            if cp != original_cp or observed != original_manifest:
                raise ValueError('Original arm does not use the exact preceding measured runtime')
            if (descriptor['sourceIdentity'] != ORIGINAL_SOURCE
                    or Path(descriptor['sourceManifestFile']).resolve() != ORIGINAL_SOURCES.resolve()):
                raise ValueError('Original arm source-map identity mismatch')
        elif any(observed[i] != original_manifest[i] for i in range(127) if i != 1):
            raise ValueError(f'Candidate changed more than production entry 1: {name}')
        if not descriptor['sourceIdentity']:
            raise ValueError(f'Missing source identity: {name}')
        snapshots[name] = {'classpath': cp, 'manifest': observed, 'descriptor': descriptor}
    for name, snapshot in snapshots.items():
        if name != 'original' and snapshot['manifest'][1]['sha256'] == original_manifest[1]['sha256']:
            raise ValueError(f'Candidate production bytes equal original: {name}')
    if snapshots['candidate1']['manifest'][1]['sha256'] == snapshots['candidate1-and-2']['manifest'][1]['sha256']:
        raise ValueError('Candidate 2 production bytes equal Candidate 1')
    for name in ('JAVA_TOOL_OPTIONS', 'JDK_JAVA_OPTIONS', '_JAVA_OPTIONS'):
        if os.environ.get(name):
            raise ValueError(f'Unprescribed JVM environment override: {name}')
    return protocol, snapshots


def route_histogram(samples):
    histogram = Counter()
    for sample in samples:
        counters = sample['counters']
        signature = {'selections': sample['successfulSelections'],
                     'compiledBinds': counters['compiledBinds'], 'interpretedBinds': counters['interpretedBinds'],
                     'aggregateCompiledBinds': counters['aggregateCompiledBinds'],
                     'aggregateInterpretedBinds': counters['aggregateInterpretedBinds'],
                     'semanticNativeCompiles': counters['semanticNativeCompiles']}
        histogram[json.dumps(signature, sort_keys=True, separators=(',', ':'))] += 1
    return [{'signature': json.loads(key), 'count': count} for key,count in sorted(histogram.items())]


def normalized_metadata(metadata):
    result = dict(metadata)
    for field in ('arm', 'source', 'store'):
        result.pop(field, None)
    result['jvmArguments'] = [x for x in result['jvmArguments'] if not x.startswith('-D' + PROPERTY + '=')]
    result['systemProperties'] = {key:value for key,value in result['systemProperties'].items() if key != PROPERTY}
    return result


def validate_run(folder, arm, runtime, mode):
    records = [json.loads(line) for line in (folder / 'samples.jsonl').read_text().splitlines()]
    if len(records) != 14 or records[0].get('type') != 'metadata':
        raise ValueError('Expected exactly one metadata record and thirteen query records')
    metadata, samples = records[0], records[1:]
    if any(s.get('type') != 'sample' for s in samples) or [s['iteration'] for s in samples] != list(range(-8, 5)):
        raise ValueError('Unexpected, failed or incomplete query sequence')
    if metadata['arm'] != arm or metadata['source'] != runtime['descriptor']['sourceIdentity']:
        raise ValueError('Raw source/arm identity mismatch')
    if metadata['systemProperties'].get(PROPERTY) != mode:
        raise ValueError('Raw transport mode mismatch')
    expected = {'canonicalGraphSha256': 'cf637a7e80dbd9468d7e8b04116da072f726038282dfab15380c267c8cc82e9b',
                'querySha256': '9cffa2dc37bbb1e2743442b228d5ab9a41115bf7c4a6667506231fbda3bfc301',
                'expectedRows': 1152000, 'expectedChecksum': '3123987218479850048', 'width': 12,
                'measurements': 100, 'readings': 10, 'statuses': 2, 'uniquePayloads': 0,
                'consumption': 'full', 'nativeEvaluation': True, 'maxHeapBytes': 1073741824,
                'warmup': 8, 'measurementsToRun': 5, 'javaVersion': '25.0.5+8-LTS'}
    if any(metadata.get(key) != value for key,value in expected.items()):
        raise ValueError('Fixture/JVM/input metadata mismatch')
    expected_jvm = ['-Xms1024m', '-Xmx1024m', '-XX:+UseG1GC', '-D' + PROPERTY + '=' + mode]
    if metadata['jvmArguments'] != expected_jvm:
        raise ValueError('Unexpected JVM arguments or profiler instrumentation')
    for sample in samples:
        if (sample['arm'] != arm or sample['stage'] != ('warmup' if sample['iteration'] < 0 else 'measurement')
                or not sample['valid'] or not sample['complete'] or sample['rows'] != 1152000
                or sample['checksum'] != '3123987218479850048'
                or sample['ledgerBeforeBytes'] != 0 or sample['ledgerAfterBytes'] != 0
                or sample['allThreadAllocatedBytes'] < 0 or sample['counters']['semanticNativeCompiles'] != 1):
            raise ValueError('Result, allocation, ledger, or per-query compilation validation failed')
        admissions = sample['counters']['coordinateAdmissions']
        if (admissions is None or admissions['opened'] != (mode != 'off')
                or admissions['initialAdmissionRefused'] != 0 or admissions['growthAdmissionRefused'] != 0):
            raise ValueError('Coordinate admission did not match the prescribed arm')
    audit = json.loads((folder / 'root-host-audit.json').read_text())
    if (not audit['harnessReturned'] or audit['hostedGenericTotal'] != 0
            or audit['semanticNativeCompilesTotal'] != 13
            or sum(s['counters']['semanticNativeCompiles'] for s in samples) != 13):
        raise ValueError('Absolute post-main root audit failed')
    measured = [s for s in samples if s['stage'] == 'measurement']
    if len(measured) != 5:
        raise ValueError('Expected all five measured queries')
    return metadata, samples, audit, measured


def run_fork(command, folder, timeout):
    started = time.time_ns()
    write_new(folder / 'command.json', {'argv': command, 'cwd': str(ROOT), 'startedEpochNs': started})
    with (folder / 'console.log').open('xb') as console:
        process = subprocess.Popen(command, cwd=ROOT, stdout=console, stderr=subprocess.STDOUT, start_new_session=True)
        try:
            deadline = time.monotonic() + timeout
            next_report = time.monotonic() + 30
            while process.poll() is None:
                now = time.monotonic()
                if now >= deadline:
                    raise TimeoutError(f'Prescribed process deadline exceeded: {timeout}s')
                if now >= next_report:
                    print('  process still running; raw output preserved', flush=True)
                    next_report = now + 30
                time.sleep(.2)
            status = process.wait()
        finally:
            if process.poll() is None:
                os.killpg(process.pid, signal.SIGTERM)
                try:
                    process.wait(timeout=15)
                except subprocess.TimeoutExpired:
                    os.killpg(process.pid, signal.SIGKILL)
                    process.wait()
    write_new(folder / 'process-result.json', {'exitCode': status, 'startedEpochNs': started,
                                             'finishedEpochNs': time.time_ns()})
    if status:
        raise RuntimeError(f'JVM exited {status}')


def summary(runs, complete, errors):
    result = {'complete': complete, 'errors': errors, 'completedJvms': len(runs),
              'rawQueryCount': sum(len(r['samples']) for r in runs),
              'rawMeasuredQueryCount': sum(sum(s['stage']=='measurement' for s in r['samples']) for r in runs),
              'comparisonStatus': 'complete prespecified protocol' if complete else 'incomplete; no accepted comparison estimates',
              'ratioDefinition': 'Candidate JVM median / comparator JVM median within the same matched round; separate fresh JVMs, never a shared fork',
              'comparisons': []}
    if not complete:
        return result
    indexed = {(r['round'],r['arm']):r for r in runs}
    for candidate, comparator in PAIRS:
        paired = []
        for round in range(4):
            a,b = indexed[round,candidate],indexed[round,comparator]
            paired.append({'round':round,'ratios':{m:a['medians'][m]/b['medians'][m] for m in METRICS},
                           'routeTierHistogramsEqual':a['routeTierHistogram']==b['routeTierHistogram']})
        result['comparisons'].append({'candidate':candidate,'comparator':comparator,'pairs':paired,
            'medianRatios':{m:statistics.median(p['ratios'][m] for p in paired) for m in METRICS},
            'ratioRanges':{m:[min(p['ratios'][m] for p in paired),max(p['ratios'][m] for p in paired)] for m in METRICS},
            'allRouteTierHistogramsEqual':all(p['routeTierHistogramsEqual'] for p in paired)})
    return result


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--protocol', type=Path, required=True)
    parser.add_argument('--output', type=Path)
    parser.add_argument('--validate-only', action='store_true')
    args = parser.parse_args()
    protocol_path = args.protocol.resolve(strict=True)
    protocol_sha = sha(protocol_path)
    protocol, snapshots = validate_protocol(protocol_path)
    if args.validate_only:
        print('Protocol/runtime validation passed; no JVM launched.')
        return
    if args.output is None:
        parser.error('--output is required when executing')
    destination = args.output.resolve()
    destination.mkdir(parents=True, exist_ok=False)
    (destination / 'used-protocol.json').write_bytes(protocol_path.read_bytes())
    watched = {}
    for name, runtime in snapshots.items():
        consumed = destination / 'runtime-identities' / name
        consumed.mkdir(parents=True)
        descriptor = runtime['descriptor']
        write_new(consumed / 'runtime-descriptor.json', descriptor)
        for field in ('classpathFile','classpathManifestFile','sourceManifestFile','provenanceFile','productionPatchFile',
                      'originalSourceManifestFile'):
            if field in descriptor:
                path = Path(descriptor[field])
                watched[str(path)] = sha(path)
                (consumed / path.name).write_bytes(path.read_bytes())
    write_new(destination / 'preflight.json', {'protocolSha256':protocol_sha,
              'runtimeManifests':{name:r['manifest'] for name,r in snapshots.items()},
              'driverSha256':sha(Path(__file__)), 'identityHelperSha256':sha(HERE / 'runtime_identity.py')})
    runs, errors = [], []
    metadata_reference = None
    for round, order in enumerate(protocol['balancedOrders']):
        if errors:
            break
        for position, arm in enumerate(order):
            folder = destination / f'round-{round:02d}-{position:02d}-{arm}'
            folder.mkdir()
            spec = protocol['armDefinitions'][arm]
            runtime, mode = snapshots[spec['runtime']], spec['transportMode']
            command = [protocol['java'], '-Xms1024m', '-Xmx1024m', '-XX:+UseG1GC',
                       '-D'+PROPERTY+'='+mode, '-cp', runtime['classpath'], MAIN,
                       '--arm='+arm, '--source='+runtime['descriptor']['sourceIdentity'],
                       '--warmup=8', '--iterations=5', '--measurements=100', '--readings=10',
                       '--width=12', '--statuses=2', '--unique-payloads=0', '--consumption=full',
                       '--output='+str(folder/'samples.jsonl'), '--store='+str(folder/'store')]
            print(f'Running round {round+1}/4, position {position+1}/4: {arm}', flush=True)
            try:
                run_fork(command, folder, protocol['timeoutSeconds'])
                metadata, samples, audit, measured = validate_run(folder, arm, runtime, mode)
                normalized = normalized_metadata(metadata)
                if metadata_reference is None:
                    metadata_reference = normalized
                elif normalized != metadata_reference:
                    raise ValueError('Normalized input/JVM metadata differs between arms')
                runs.append({'round':round,'position':position,'arm':arm,'runtime':spec['runtime'],
                             'transportMode':mode,'directory':str(folder),'metadata':metadata,'samples':samples,
                             'rootAudit':audit,'medians':{m:statistics.median(s[m] for s in measured) for m in METRICS},
                             'routeTierHistogram':route_histogram(measured)})
                print(f'  completed {len(runs)}/16; all 13 queries valid; HOSTED_GENERIC=0', flush=True)
            except Exception as error:
                errors.append({'round':round,'arm':arm,'directory':str(folder),'exception':type(error).__name__,
                               'message':str(error),'policy':'Preserve all raw records and stop; no replacement or silent exclusion'})
                print('  BLOCKED: '+str(error),flush=True)
            (destination/'runs.json').write_text(json.dumps(runs,indent=2)+'\n')
            (destination/'summary.json').write_text(json.dumps(summary(runs,False,errors),indent=2)+'\n')
            if errors:
                break
    post = {'protocolUnchanged':sha(protocol_path)==protocol_sha,
            'driverUnchanged':sha(Path(__file__))==protocol['driverSha256'],
            'helperUnchanged':sha(HERE/'runtime_identity.py')==protocol['identityHelperSha256'],
            'identityFilesUnchanged':all(Path(path).is_file() and sha(path)==expected for path,expected in watched.items()),
            'runtimeIdentitiesUnchanged':{name:classpath_manifest(r['classpath'])==r['manifest'] for name,r in snapshots.items()}}
    write_new(destination/'post-run-preservation.json',post)
    if not all([post['protocolUnchanged'],post['driverUnchanged'],post['helperUnchanged'],post['identityFilesUnchanged'],
                *post['runtimeIdentitiesUnchanged'].values()]):
        errors.append({'message':'Protocol, driver/helper, or frozen runtime identity changed'})
    final = summary(runs,len(runs)==16 and not errors,errors)
    (destination/'summary.json').write_text(json.dumps(final,indent=2)+'\n')
    if errors:
        raise SystemExit(1)


if __name__ == '__main__':
    main()
